.phone-wrapper { all: initial; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif; display: block; box-sizing: border-box; width: 380px; max-width: 95vw; height: 820px; max-height: 95vh; background: #0a0a0a; border-radius: 48px; padding: 10px; box-shadow: 0 0 0 2px #222, 0 0 0 6px #0a0a0a, 0 0 0 8px #1a1a1a, 0 20px 50px rgba(0,0,0,0.6); margin: 20px auto; color: #000; position: relative; }
.phone-wrapper * { all: unset; display: revert; box-sizing: border-box; font-family: inherit; color: inherit; }
.phone-wrapper span { display: inline; }
.phone-wrapper details { display: block; }
.phone-wrapper summary { cursor: pointer; list-style: none; outline: none; }
.phone-wrapper summary::-webkit-details-marker { display: none; }
